"""stages.verify.cost: generated by the graph.py split (P1)."""

from __future__ import annotations

from pathlib import Path

from ...flow import gates, ladder, outcome
from ...runtime import effects, commands, stage_services
from ...runtime.tools import SOC_WORKSPACE_SUBDIR
from ...stages.verify import software
from ...state import CfuDesignState


def estimate_cost(state: CfuDesignState) -> CfuDesignState:
    if state.get("skip_yosys", False):
        result = [stage_services._skipped_result("python3 skills/cfu-designer/scripts/yosys_cost_report.py", state, "--skip-yosys")]
        stage_services._write_cost_artifact(state, result, "planned", "--skip-yosys")
        return {
            "cost_results": result,
            "stage_jobs": "review",
            **outcome.stage_result(state, rung="cost", ok=False, skipped=True,
                                   reason="--skip-yosys",
                                   history="Skipped Yosys cost estimation by request."),
        }

    toolbox = stage_services._toolbox_for_stage(state, "cost")
    agent_cfu = gates.is_agent_cfu_run(state)
    spec = state.get("workload_spec", {}) or {}
    task = state.get("task", "")
    case = commands.cost_case_for_spec(spec, task, agent_cfu=agent_cfu)
    execute = bool(state.get("run_commands", False))
    workdir = Path(state.get("workdir", ".")).resolve()

    # Command side effects must stay inside the stage's declared write roots, so
    # the report goes into the run directory when one exists.
    run_root = state.get("run_root", "")
    if run_root:
        out_dir = f"{run_root}/11_cost/yosys/{case}"
        # NOTE: the cost rung derives its AgentCfu flags from the ISA spec
        # internally -- never pass the workload spec here (that mismatch made
        # cost re-elaborate the CFU with default parameters).
        generator_commands = commands.agent_cfu_cost_commands(state) if agent_cfu else []
        rtl = (
            f"{run_root}/11_cost/cfu_rtl"
            if generator_commands
            else f"{run_root}/{SOC_WORKSPACE_SUBDIR}/MiCoSoc.v"
        )
    else:
        out_dir = f"{stage_services.base_artifact_root(state)}/yosys/{case}"
        generator_commands = []
        rtl = "MiCoSoc.v"

    yosys_command = [
        "python3",
        "skills/cfu-designer/scripts/yosys_cost_report.py",
        rtl,
        "--top",
        commands.cost_top_for_spec(spec, task, agent_cfu=agent_cfu),
        "--out-dir",
        out_dir,
        "--flatten",
    ]

    results: list[dict] = []
    errors: list[str] = []
    if not execute:
        for argv in [*generator_commands, yosys_command]:
            results.append(toolbox.run_command(argv, execute=False))
        ok = False
    else:
        # Agent runs synthesize the standalone CFU first: GenAgentCfu elaborates
        # only the overlaid AgentCfu class, so Yosys never sees the CPU/SoC.
        for argv in generator_commands:
            result = effects.run_command(state, toolbox, argv, stage="cost", rung="cost", timeout=1800, mutate=True)
            results.append(result)
            if result.get("returncode") not in (0, None):
                errors.append(f"CFU generation failed: {' '.join(argv)[:200]}")
                break
        if not errors and generator_commands and not software._rtl_ready(workdir, rtl):
            errors.append(f"CFU generation produced no Verilog under {rtl}")
        if not errors:
            result = effects.run_command(state, toolbox, yosys_command, stage="cost", rung="cost", timeout=1800, mutate=True)
            results.append(result)
            if result.get("returncode") not in (0, None):
                errors.append(f"Yosys cost estimation failed: {' '.join(yosys_command)[:200]}")
        ok = not errors and bool(results) and all(item.get("returncode") == 0 for item in results)

    reason = "; ".join(errors)[:400] if errors else ""
    stage_services._write_cost_artifact(
        state, results, "passed" if ok else ("planned" if not execute else "failed"), reason
    )
    extra, next_node = ladder._ladder_transition(
        state,
        "cost",
        ok=ok,
        default="review_and_route",
        repair_target="implement",
        skipped=not execute,
    )
    update = {
        "cost_results": results,
        "stage_jobs": "review",
        "errors": errors,
        **outcome.stage_result(
            state, rung="cost", ok=ok, skipped=not execute, next=next_node,
            reason=reason or ("" if execute else "execution-disabled"),
            rtl=rtl, round=int(state.get("optimization_round", 0) or 0),
            history="Ran Yosys cost estimation.",
        ),
    }
    return ladder._apply_transition(update, extra)
